def figure(a, w, c, d, ta, tw, tc, td):
    b = a.conjugate()
    return plan("Les points A, B, C, D et Ω", f"a = {ta}, b = ā, c = {tc}, ω = {tw}, d = {td}.",
                [("A", a.real, a.imag, "cyan", "no"), ("B", b.real, b.imag, "cyan", "so"), ("C", c.real, c.imag, "orange", "ne"),
                 ("Ω", w.real, w.imag, "jaune", "s"), ("D", d.real, d.imag, "vert", "ne")],
                xs=(-1, int(c.real) + 1), ys=(-int(a.imag) - 1, int(a.imag) + 1))


